WITH flattened AS (SELECT id, customer_id, created_at, line.product_id, line.price FROM (SELECT id, customer_id, created_at, EXPLODE_OUTER(items) AS line FROM carts) t), valid AS (SELECT *, ROUND(price * 0.9, 2) AS price_scaled FROM flattened WHERE customer_id IS NOT NULL), enriched AS (SELECT *, RANK() OVER (ORDER BY price DESC NULLS FIRST) AS price_rank, SUM(price_scaled) OVER w_running AS customer_id_sum_price_scaled, ROUND(product_id / SUM(product_id) OVER (PARTITION BY customer_id), 4) AS product_id_share, CUME_DIST() OVER (PARTITION BY customer_id ORDER BY product_id) AS product_id_cume_dist, DENSE_RANK() OVER (PARTITION BY customer_id ORDER BY price_scaled DESC NULLS FIRST) AS price_scaled_dense_rank FROM valid WINDOW w_running AS (PARTITION BY customer_id)), with_windows AS (SELECT id, customer_id, created_at, product_id, price, price_scaled, price_rank, customer_id_sum_price_scaled, product_id_share, product_id_cume_dist, price_scaled_dense_rank, RANK() OVER (PARTITION BY customer_id ORDER BY product_id DESC NULLS FIRST) AS product_id_rank, AVG(price) OVER (PARTITION BY customer_id) AS customer_id_avg_price, SUM(price_scaled) OVER (PARTITION BY customer_id ORDER BY CAST(created_at AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW) AS price_scaled_sum_1h FROM enriched), filtered AS (SELECT *, CAST(customer_id_avg_price AS DOUBLE) AS customer_id_avg_price_str FROM with_windows WHERE created_at >= DATE '2025-03-02' AND price_rank >= 7), cleaned AS (SELECT customer_id, created_at, product_id, price, price_scaled, price_rank, customer_id_sum_price_scaled, product_id_cume_dist, product_id_rank, customer_id_avg_price, price_scaled_sum_1h, customer_id_avg_price_str, GREATEST(price_scaled_dense_rank, price_scaled) AS greatest_price_scaled_dense_rank_price_scaled FROM filtered WHERE TO_DATE(created_at) < '2024-01-16') SELECT customer_id, created_at, price, price_scaled, price_rank, product_id_cume_dist, product_id_rank, price_scaled_sum_1h, customer_id_avg_price_str FROM cleaned ORDER BY customer_id NULLS LAST;
